import React, { useState, ImgHTMLAttributes } from 'react';

interface FallbackImageProps extends ImgHTMLAttributes<HTMLImageElement> {
  fallbackSrc?: string;
}

const defaultFallback = 'data:image/svg+xml;base64,';

export default function FallbackImage({ src, fallbackSrc = defaultFallback, alt = '', ...props }: FallbackImageProps) {
  const [imgSrc, setImgSrc] = useState(src);
  const [error, setError] = useState(false);

  const handleError = () => {
    if (!error) {
      setError(true);
      setImgSrc(fallbackSrc);
    }
  };

  return (
    <img
      src={imgSrc}
      alt={alt}
      onError={handleError}
      {...props}
    />
  );
}
